SELECT country,business,channel,type,resource,supplier_name,system_abbr,unit_price,vat_rate,pricing_method,currency_unit,effective_start_date,effective_end_date,create_time FROM dm_wd_efficiency.dim_supplier_price WHERE country='印尼' AND channel='AI' AND effective_start_date<'2026-11-14' AND (effective_end_date IS NULL OR effective_end_date>='2026-11-01') ORDER BY supplier_name,type,effective_start_date
